package com.skillswap.service;
import com.skillswap.model.User; import com.skillswap.repository.UserRepository; import com.skillswap.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class AuthService {private final UserRepository repo;private final PasswordEncoder enc;private final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} public Map<String,Object> register(User u){if(repo.findByEmail(u.getEmail()).isPresent())throw new RuntimeException("Email already registered");u.setPassword(enc.encode(u.getPassword()));repo.save(u);return login(u.getEmail(),u.getPassword(),true);} public Map<String,Object> login(String email,String password,boolean encoded){User u=repo.findByEmail(email).orElseThrow(()->new RuntimeException("Invalid credentials"));if(!encoded&&!enc.matches(password,u.getPassword()))throw new RuntimeException("Invalid credentials");return Map.of("token",jwt.generate(u.getEmail()),"userId",u.getId(),"name",u.getName(),"email",u.getEmail());} }
